/**
 * Ownership-handover offers. Every read is filtered by `orgId`.
 *
 * Lapsing is decided by the service from `expiresAt`; a row stays `pending`
 * until something resolves it.
 */
import { and, eq, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, members, organizations, ownershipHandovers } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toOwnershipHandover } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { Role } from "@/types/member";
import type {
  OwnershipHandover,
  OwnershipHandoverStatus,
} from "@/types/organization";

/** The newest offer still marked `pending` (it may already have lapsed). */
export async function findPendingHandover(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const rows = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .all();
  const newest = rows.sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1))[0];
  return newest ? toOwnershipHandover(newest) : null;
}

export async function insertHandover(input: {
  readonly orgId: OrgId;
  readonly fromUserId: UserId;
  readonly toUserId: UserId;
  readonly createdAt: IsoTimestamp;
  readonly expiresAt: IsoTimestamp;
}): Promise<OwnershipHandover> {
  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId: input.orgId,
      fromUserId: input.fromUserId,
      toUserId: input.toUserId,
      status: "pending",
      expiresAt: input.expiresAt,
      resolvedAt: null,
      createdAt: input.createdAt,
      updatedAt: input.createdAt,
    })
    .returning()
    .get();
  return toOwnershipHandover(row);
}

export async function resolveHandover(
  orgId: OrgId,
  handoverId: string,
