  if (toUserId === actor.userId) throw new OwnershipHandoverError("self");

  const now = new Date();
  const pending = await handoverRepo.findPendingHandover(orgId);
  if (pending) {
    if (!hasLapsed(pending, now)) {
      throw new OwnershipHandoverError("pending_exists");
    }
    await handoverRepo.resolveHandover(
      orgId,
      pending.id,
      "expired",
      toIsoTimestamp(new Date(pending.expiresAt)),
    );
  }

  const handover = await handoverRepo.insertHandover({
    orgId,
    fromUserId: actor.userId,
    toUserId,
    createdAt: toIsoTimestamp(now),
    expiresAt: toIsoTimestamp(new Date(now.getTime() + HANDOVER_TTL_MS)),
  });

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "Ownership of this workspace was offered to you",
    body: `${actor.userId} offered you ownership of the workspace`,
    href: "/settings/ownership",
    actorId: actor.userId,
  });

  return handover;
}

/**
 * Only the offered member can act on the offer; anyone else, and every caller
 * when nothing is open, gets `nothing_pending`. A lapsed offer is `expired`
 * for the offered member and is left untouched.
 */
async function requireOfferedHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  const pending = await handoverRepo.findPendingHandover(orgId);
  if (!pending || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (hasLapsed(pending, new Date())) throw new OwnershipHandoverError("expired");
  return pending;
}

/**
 * The offered member becomes the recorded owner and holds the owner role; the
 * previous owner steps down to admin. The new owner is promoted first, so the
 * workspace has an owner at every instant.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const pending = await requireOfferedHandover(actor, orgId);

  const swap = handoverRepo.swapOwnership({
    orgId,
    handoverId: pending.id,
    fromUserId: pending.fromUserId,
    toUserId: pending.toUserId,
    at: toIsoTimestamp(new Date()),
  });
  if (swap === null) throw new OwnershipHandoverError("nothing_pending");

  if (swap.newOwnerRoleBefore !== "owner") {
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: swap.newOwnerMemberId as MemberId,
      from: swap.newOwnerRoleBefore,
      to: "owner",
    });
  }

  if (swap.previousOwnerMemberId !== null && swap.previousOwnerRoleBefore === "owner") {
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: swap.previousOwnerMemberId as MemberId,
      from: "owner",
      to: "admin",
    });
  }

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: pending.fromUserId,
    toUserId: pending.toUserId,
  });

  return requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const pending = await requireOfferedHandover(actor, orgId);
  return handoverRepo.resolveHandover(
    orgId,
    pending.id,
    "declined",
    toIsoTimestamp(new Date()),
  );
}

/** The withdrawal: the recorded owner takes back an open offer. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  await assertRecordedOwner(actor, orgId);

  const open = await findOpenHandover(orgId, new Date());
  if (!open) throw new OwnershipHandoverError("nothing_pending");

  return handoverRepo.resolveHandover(
    orgId,
    open.id,
    "canceled",
    toIsoTimestamp(new Date()),
  );
}

/** Visible to every member of the workspace. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));
  return findOpenHandover(orgId, new Date());
}
