import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { OwnershipHandoverError } from "@/lib/errors";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { removeMember } from "@/server/services/member-service";
import {
  acceptOwnershipHandover,
  cancelOwnershipHandover,
  declineOwnershipHandover,
  getPendingOwnershipHandover,
  initiateOwnershipHandover,
} from "@/server/services/organization-service";
import { PermissionDeniedError } from "@/lib/permissions";
import { createTenant, useTemporaryDatabase, type Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});
afterAll(() => cleanup());

async function refusal(promise: Promise<unknown>): Promise<string> {
  try {
    await promise;
  } catch (error) {
    if (error instanceof OwnershipHandoverError) return error.reason;
    throw error;
  }
  return "none";
}

describe("ownership handover", () => {
  it("hands the workspace over on acceptance", async () => {
    const t: Tenant = await createTenant("handover-a");
    const { owner, admin } = t.actors;
    await initiateOwnershipHandover(owner, t.org.id, admin.userId);
    expect((await getPendingOwnershipHandover(t.actors.viewer, t.org.id))?.toUserId).toBe(admin.userId);
    expect(await refusal(initiateOwnershipHandover(owner, t.org.id, admin.userId))).toBe("pending_exists");
    expect(await refusal(acceptOwnershipHandover(t.actors.member, t.org.id))).toBe("nothing_pending");

    const org = await acceptOwnershipHandover(admin, t.org.id);
    expect(org.ownerId).toBe(admin.userId);
    expect((await memberRepo.findMember(t.org.id, admin.userId))?.role).toBe("owner");
    expect((await memberRepo.findMember(t.org.id, owner.userId))?.role).toBe("admin");
    expect(await getPendingOwnershipHandover(owner, t.org.id)).toBeNull();
    expect(await refusal(acceptOwnershipHandover(admin, t.org.id))).toBe("nothing_pending");
  });

  it("refuses non-recorded owners, self and outsiders", async () => {
    const t = await createTenant("handover-b");
    const { owner, admin, member } = t.actors;
    await expect(
      initiateOwnershipHandover({ ...admin, role: "owner" }, t.org.id, member.userId),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(await refusal(initiateOwnershipHandover(owner, t.org.id, owner.userId))).toBe("self");
    expect(await refusal(cancelOwnershipHandover(owner, t.org.id))).toBe("nothing_pending");
