      const offer = await initiateOwnershipHandover(owner, t.org.id, member.userId);
      expect(offer.expiresAt).toBe("2026-01-08T00:00:00.000Z");
      vi.setSystemTime(new Date("2026-01-07T23:59:59.999Z"));
      expect(await getPendingOwnershipHandover(owner, t.org.id)).not.toBeNull();
      vi.setSystemTime(new Date("2026-01-08T00:00:00.000Z"));
      expect(await getPendingOwnershipHandover(owner, t.org.id)).toBeNull();
      expect(await refusal(acceptOwnershipHandover(member, t.org.id))).toBe("expired");
      expect(await refusal(declineOwnershipHandover(member, t.org.id))).toBe("expired");
      await initiateOwnershipHandover(owner, t.org.id, member.userId);
    } finally {
      vi.useRealTimers();
    }
  });

  it("declines, withdraws, and auto-withdraws on removal", async () => {
    const t = await createTenant("handover-d");
    const { owner, admin, member } = t.actors;
    await initiateOwnershipHandover(owner, t.org.id, member.userId);
    expect((await declineOwnershipHandover(member, t.org.id)).status).toBe("declined");
    await initiateOwnershipHandover(owner, t.org.id, member.userId);
    expect((await cancelOwnershipHandover(owner, t.org.id)).status).toBe("canceled");
    await initiateOwnershipHandover(owner, t.org.id, member.userId);
    const target = await memberRepo.findMember(t.org.id, member.userId);
    await removeMember(admin, { orgId: t.org.id, memberId: target!.id });
    expect(await getPendingOwnershipHandover(owner, t.org.id)).toBeNull();
    expect((await orgRepo.findOrgById(t.org.id))?.ownerId).toBe(owner.userId);
  });
});
